SELECT jsonb_build_object('users',(select count(*) from users),'days',(select jsonb_agg(jsonb_build_array(d,(select count(*) from doors where day=d),(select count(*) from spins where day=d),(select count(*) from tickets where day=d)) order by d) from generate_series(1,20)d),'games',(select coalesce(jsonb_object_agg(game,n),'{}') from (select game,count(*) n from attempts group by game)s),'locations',(select coalesce(jsonb_object_agg(location,n),'{}') from(select location,count(*) n from users group by location)s),'wheel',(select coalesce(jsonb_object_agg(reward,n),'{}') from(select reward,count(*) n from spins group by reward)s),'prizes',(select data->'prizes' from proof),'jobs',(select coalesce(jsonb_object_agg(status,n),'{}') from(select status,count(*) n from jobs group by status)s),'review',(select coalesce(jsonb_agg(to_jsonb(s)),'[]') from(select a.id,nick,game,score,step,flagged from attempts a join users u on a.uid=u.id where flagged or step>=40 order by issued desc limit 100)s),'audit',(select coalesce(jsonb_agg(to_jsonb(s)),'[]') from(select created,action,detail from audit order by id desc limit 40)s))
